query SearchRelatedNodes($sourceNodeId: ID!, $relationTypeIds: [ID!], $direction: RelationDirection = OUTGOING, $maxDepth: Int = 1, $limit: Int = 20, $offset: Int = 0) {
  searchRelatedNodes(
    filter: {
      sourceNodeId: $sourceNodeId
      relationTypeIds: $relationTypeIds
      direction: $direction
      maxDepth: $maxDepth
    }
    pagination: {
      limit: $limit
      offset: $offset
    }
  ) {
    nodes {
      id
      content
      table {
        id
        identifier
      }
      attributeCount
      relationCount
      connectedNodes(depth: 1, direction: BOTH) {
        node {
          id
          content
        }
        depth
      }
    }
    relations {
      id
      relationType {
        identifier
        name
      }
      sourceNode {
        id
        content
      }
      targetNode {
        id
        content
      }
    }
    totalCount
    hasNextPage
    hasPreviousPage
  }
}
